// src/components/layout/Sidebar.js
import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTheme } from '../../contexts/ThemeContext';

export default function Sidebar() {
  const location = useLocation();
  const { isDark } = useTheme();
  const [isCollapsed, setIsCollapsed] = useState(false);

  const menuItems = [
    { path: '/dashboard', label: 'Dashboard', icon: '📊' },
    { path: '/trading', label: 'Trading', icon: '💹' },
    { path: '/portfolio', label: 'Portfolio', icon: '💰' },
    { path: '/market', label: 'Market Data', icon: '📈' },
    { path: '/models', label: 'AI Models', icon: '🤖' },
    { path: '/backtest', label: 'Backtesting', icon: '🔍' },
    { path: '/analytics', label: 'Analytics', icon: '📋' },
  ];

  return (
    <>
      {/* Overlay for mobile */}
      {isCollapsed && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden"
          onClick={() => setIsCollapsed(false)}
        />
      )}
      
      <div className={`bg-white dark:bg-gray-800 shadow-lg fixed left-0 top-16 h-full border-r border-gray-200 dark:border-gray-700 transition-all duration-300 z-50 ${
        isCollapsed ? 'w-16' : 'w-64'
      }`}>
        {/* Toggle Button */}
        <button
          onClick={() => setIsCollapsed(!isCollapsed)}
          className={`absolute -right-3 top-6 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-full p-1 shadow-lg transition-colors duration-300 ${
            isCollapsed ? 'rotate-180' : ''
          }`}
        >
          <svg className="w-4 h-4 text-gray-600 dark:text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
        </button>

        <nav className="mt-8">
          <ul className="space-y-2 px-3">
            {menuItems.map((item) => (
              <li key={item.path}>
                <Link
                  to={item.path}
                  className={`flex items-center px-3 py-3 rounded-xl transition-all duration-300 ${
                    location.pathname === item.path
                      ? 'bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white border-l-4 border-blue-500'
                      : 'text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-700/50'
                  } ${isCollapsed ? 'justify-center' : ''}`}
                  title={isCollapsed ? item.label : ''}
                >
                  <span className={`${isCollapsed ? 'text-lg' : 'text-base mr-3'}`}>
                    {item.icon}
                  </span>
                  {!isCollapsed && (
                    <span className="font-medium text-sm">{item.label}</span>
                  )}
                </Link>
              </li>
            ))}
          </ul>
        </nav>

        {/* Quick Stats */}
        {!isCollapsed && (
          <div className="absolute bottom-6 left-4 right-4">
            <div className={`rounded-xl p-3 border transition-colors duration-300 ${
              isDark
                ? 'bg-gray-700 border-gray-600'
                : 'bg-gray-50 border-gray-200'
            }`}>
              <p className={`text-xs font-medium ${
                isDark ? 'text-gray-200' : 'text-gray-700'
              }`}>Trading Status</p>
              <div className="flex items-center mt-1">
                <div className="w-2 h-2 bg-green-500 rounded-full mr-2"></div>
                <span className={`text-xs ${
                  isDark ? 'text-gray-400' : 'text-gray-600'
                }`}>Connected</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </>
  );
}
